            12'd2338: str_chr = 8'h53;
            12'd2339: str_chr = 8'h54;
            12'd2340: str_chr = 8'h45;
            12'd2341: str_chr = 8'h4D;
            // sid 74  PR_0 : "NONE"
            12'd2368: str_chr = 8'h4E;
            12'd2369: str_chr = 8'h4F;
            12'd2370: str_chr = 8'h4E;
            12'd2371: str_chr = 8'h45;
            // sid 75  PR_1 : "TCP"
            12'd2400: str_chr = 8'h54;
            12'd2401: str_chr = 8'h43;
            12'd2402: str_chr = 8'h50;
            // sid 76  PR_2 : "UDP"
            12'd2432: str_chr = 8'h55;
            12'd2433: str_chr = 8'h44;
            12'd2434: str_chr = 8'h50;
            // sid 77  PR_3 : "ICMP"
            12'd2464: str_chr = 8'h49;
            12'd2465: str_chr = 8'h43;
            12'd2466: str_chr = 8'h4D;
            12'd2467: str_chr = 8'h50;
            // sid 78  PR_4 : "OTHER"
            12'd2496: str_chr = 8'h4F;
            12'd2497: str_chr = 8'h54;
            12'd2498: str_chr = 8'h48;
            12'd2499: str_chr = 8'h45;
            12'd2500: str_chr = 8'h52;
                default: str_chr = 8'h3F;   // '?'
            endcase
        end
    endfunction

    function [4:0] str_len;
        input [6:0] s;
        begin
            case (s)
            7'd0: str_len = 5'd11;   // L_HDR
            7'd1: str_len = 5'd6;   // L_ID
            7'd2: str_len = 5'd6;   // L_UP
            7'd3: str_len = 5'd8;   // L_SEV
            7'd4: str_len = 5'd10;   // L_RULE
            7'd5: str_len = 5'd8;   // L_RID
            7'd6: str_len = 5'd9;   // L_SMAC
            7'd7: str_len = 5'd10;   // L_DMAC
            7'd8: str_len = 5'd9;   // L_SIP
            7'd9: str_len = 5'd9;   // L_DIP
            7'd10: str_len = 5'd8;   // L_PR
            7'd11: str_len = 5'd7;   // L_SP
            7'd12: str_len = 5'd6;   // L_DP
            7'd13: str_len = 5'd7;   // L_EV
            7'd14: str_len = 5'd8;   // L_VAL
            7'd15: str_len = 5'd7;   // L_ST
            7'd16: str_len = 5'd8;   // L_SUP
            7'd17: str_len = 5'd8;   // L_LOST
            7'd18: str_len = 5'd8;   // L_CRC
            7'd19: str_len = 5'd4;   // L_END
            7'd20: str_len = 5'd1;   // L_COLON
            7'd21: str_len = 5'd1;   // L_DOT
            7'd22: str_len = 5'd13;   // L_HB
            7'd23: str_len = 5'd4;   // SEV_0
            7'd24: str_len = 5'd3;   // SEV_1
            7'd25: str_len = 5'd4;   // SEV_2
            7'd26: str_len = 5'd8;   // SEV_3
            7'd27: str_len = 5'd7;   // RULE_0
            7'd28: str_len = 5'd13;   // RULE_1
            7'd29: str_len = 5'd9;   // RULE_2
            7'd30: str_len = 5'd15;   // RULE_3
            7'd31: str_len = 5'd16;   // RULE_4
            7'd32: str_len = 5'd16;   // RULE_5
            7'd33: str_len = 5'd19;   // RULE_6
            7'd34: str_len = 5'd20;   // RULE_7
            7'd35: str_len = 5'd9;   // RULE_8
            7'd36: str_len = 5'd16;   // RULE_9
            7'd37: str_len = 5'd14;   // RULE_10
            7'd38: str_len = 5'd7;   // RULE_11
            7'd39: str_len = 5'd13;   // RULE_12
            7'd40: str_len = 5'd13;   // RULE_13
            7'd41: str_len = 5'd22;   // RULE_14
            7'd42: str_len = 5'd17;   // RULE_15
            7'd43: str_len = 5'd4;   // EV_0
            7'd44: str_len = 5'd14;   // EV_1
            7'd45: str_len = 5'd15;   // EV_2
            7'd46: str_len = 5'd15;   // EV_3
            7'd47: str_len = 5'd14;   // EV_4
            7'd48: str_len = 5'd11;   // EV_5
            7'd49: str_len = 5'd18;   // EV_6
            7'd50: str_len = 5'd11;   // EV_7
            7'd51: str_len = 5'd14;   // EV_8
            7'd52: str_len = 5'd12;   // EV_9
            7'd53: str_len = 5'd19;   // EV_10
            7'd54: str_len = 5'd15;   // EV_11
            7'd55: str_len = 5'd10;   // EV_12
            7'd56: str_len = 5'd10;   // EV_13
            7'd57: str_len = 5'd13;   // EV_14
            7'd58: str_len = 5'd13;   // EV_15
            7'd59: str_len = 5'd10;   // EV_16
            7'd60: str_len = 5'd11;   // EV_17
            7'd61: str_len = 5'd12;   // EV_18
            7'd62: str_len = 5'd14;   // EV_19
            7'd63: str_len = 5'd16;   // EV_20
            7'd64: str_len = 5'd12;   // EV_21
            7'd65: str_len = 5'd12;   // EV_22
            7'd66: str_len = 5'd8;   // EV_23
            7'd67: str_len = 5'd17;   // EV_24
            7'd68: str_len = 5'd18;   // ST_0
            7'd69: str_len = 5'd10;   // ST_1
            7'd70: str_len = 5'd7;   // ST_2
            7'd71: str_len = 5'd8;   // ST_3
            7'd72: str_len = 5'd18;   // ST_4
            7'd73: str_len = 5'd6;   // ST_5
            7'd74: str_len = 5'd4;   // PR_0
            7'd75: str_len = 5'd3;   // PR_1
            7'd76: str_len = 5'd3;   // PR_2
            7'd77: str_len = 5'd4;   // PR_3
            7'd78: str_len = 5'd5;   // PR_4
                default: str_len = 5'd1;
            endcase
        end
    endfunction

    //--------------------------------------------------------------------------
    // Token program: {type, argument}.  For T_STR the argument is a string id,
    // for T_DEC / T_HEX2 it is a field id (see fval below).
    //--------------------------------------------------------------------------
    function [10:0] tok_rom;
        input [7:0] t;
        begin
            case (t)
            8'd0: tok_rom = {4'd0, 7'd0};   // STR L_HDR
            8'd1: tok_rom = {4'd1, 7'd0};   // DEC
            8'd2: tok_rom = {4'd0, 7'd1};   // STR L_ID
            8'd3: tok_rom = {4'd1, 7'd1};   // DEC
            8'd4: tok_rom = {4'd0, 7'd2};   // STR L_UP
            8'd5: tok_rom = {4'd1, 7'd2};   // DEC
            8'd6: tok_rom = {4'd0, 7'd3};   // STR L_SEV
            8'd7: tok_rom = {4'd3, 7'd0};   // SEVN
            8'd8: tok_rom = {4'd0, 7'd4};   // STR L_RULE
            8'd9: tok_rom = {4'd4, 7'd0};   // RULEN
            8'd10: tok_rom = {4'd0, 7'd5};   // STR L_RID
            8'd11: tok_rom = {4'd1, 7'd3};   // DEC
            8'd12: tok_rom = {4'd0, 7'd6};   // STR L_SMAC
            8'd13: tok_rom = {4'd2, 7'd20};   // HEX2
            8'd14: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd15: tok_rom = {4'd2, 7'd21};   // HEX2
            8'd16: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd17: tok_rom = {4'd2, 7'd22};   // HEX2
            8'd18: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd19: tok_rom = {4'd2, 7'd23};   // HEX2
            8'd20: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd21: tok_rom = {4'd2, 7'd24};   // HEX2
            8'd22: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd23: tok_rom = {4'd2, 7'd25};   // HEX2
            8'd24: tok_rom = {4'd0, 7'd7};   // STR L_DMAC
            8'd25: tok_rom = {4'd2, 7'd26};   // HEX2
            8'd26: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd27: tok_rom = {4'd2, 7'd27};   // HEX2
            8'd28: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd29: tok_rom = {4'd2, 7'd28};   // HEX2
            8'd30: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd31: tok_rom = {4'd2, 7'd29};   // HEX2
            8'd32: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd33: tok_rom = {4'd2, 7'd30};   // HEX2
            8'd34: tok_rom = {4'd0, 7'd20};   // STR L_COLON
            8'd35: tok_rom = {4'd2, 7'd31};   // HEX2
            8'd36: tok_rom = {4'd0, 7'd8};   // STR L_SIP
            8'd37: tok_rom = {4'd1, 7'd4};   // DEC
            8'd38: tok_rom = {4'd0, 7'd21};   // STR L_DOT
            8'd39: tok_rom = {4'd1, 7'd5};   // DEC
            8'd40: tok_rom = {4'd0, 7'd21};   // STR L_DOT
            8'd41: tok_rom = {4'd1, 7'd6};   // DEC
            8'd42: tok_rom = {4'd0, 7'd21};   // STR L_DOT
            8'd43: tok_rom = {4'd1, 7'd7};   // DEC
            8'd44: tok_rom = {4'd0, 7'd9};   // STR L_DIP
            8'd45: tok_rom = {4'd1, 7'd8};   // DEC
            8'd46: tok_rom = {4'd0, 7'd21};   // STR L_DOT
            8'd47: tok_rom = {4'd1, 7'd9};   // DEC
            8'd48: tok_rom = {4'd0, 7'd21};   // STR L_DOT
            8'd49: tok_rom = {4'd1, 7'd10};   // DEC
            8'd50: tok_rom = {4'd0, 7'd21};   // STR L_DOT
            8'd51: tok_rom = {4'd1, 7'd11};   // DEC
            8'd52: tok_rom = {4'd0, 7'd10};   // STR L_PR
            8'd53: tok_rom = {4'd7, 7'd0};   // PRN
            8'd54: tok_rom = {4'd0, 7'd11};   // STR L_SP
            8'd55: tok_rom = {4'd1, 7'd12};   // DEC
            8'd56: tok_rom = {4'd0, 7'd12};   // STR L_DP
            8'd57: tok_rom = {4'd1, 7'd13};   // DEC
            8'd58: tok_rom = {4'd0, 7'd13};   // STR L_EV
            8'd59: tok_rom = {4'd5, 7'd0};   // EVN
            8'd60: tok_rom = {4'd0, 7'd14};   // STR L_VAL
            8'd61: tok_rom = {4'd1, 7'd14};   // DEC
            8'd62: tok_rom = {4'd0, 7'd15};   // STR L_ST
            8'd63: tok_rom = {4'd6, 7'd0};   // STN
            8'd64: tok_rom = {4'd0, 7'd16};   // STR L_SUP
            8'd65: tok_rom = {4'd1, 7'd15};   // DEC
            8'd66: tok_rom = {4'd0, 7'd17};   // STR L_LOST
            8'd67: tok_rom = {4'd1, 7'd16};   // DEC
            8'd68: tok_rom = {4'd0, 7'd18};   // STR L_CRC
            8'd69: tok_rom = {4'd8, 7'd0};   // CRC4
            8'd70: tok_rom = {4'd0, 7'd19};   // STR L_END
            8'd71: tok_rom = {4'd9, 7'd0};   // END
            8'd72: tok_rom = {4'd0, 7'd22};   // STR L_HB
                default: tok_rom = {4'd9, 7'd0};   // END
            endcase
        end
    endfunction

    function [7:0] hexc;
        input [3:0] n;
        begin hexc = (n < 4'd10) ? (8'h30 + {4'd0, n}) : (8'h37 + {4'd0, n}); end
    endfunction

    // CRC-16/CCITT-FALSE, one byte
    function [15:0] crc16_byte;
        input [15:0] c;
        input [7:0]  d;
        integer      i;
        reg   [15:0] x;
        begin
            x = c ^ {d, 8'h00};
            for (i = 0; i < 8; i = i + 1)
                x = x[15] ? ((x << 1) ^ 16'h1021) : (x << 1);
            crc16_byte = x;
        end
    endfunction

    // Double-dabble helper: add 3 to every BCD nibble >= 5
    function [39:0] bcd_adj;
        input [39:0] b;
        integer      k;
        reg   [39:0] t;
        begin
            t = b;
            for (k = 0; k < 10; k = k + 1)
                if (t[4*k +: 4] >= 4'd5) t[4*k +: 4] = t[4*k +: 4] + 4'd3;
            bcd_adj = t;
        end
    endfunction

    //--------------------------------------------------------------------------
    // State
    //--------------------------------------------------------------------------
    (* ASYNC_REG = "TRUE" *) reg rq1 = 1'b0, rq2 = 1'b0;   // x_req synchroniser

    reg [2:0]   state;
    reg [324:0] r_rec;
    reg         msg_hb;
    reg [23:0]  cur_id;
    reg [31:0]  cur_up;
    reg [7:0]   tk;
    reg [4:0]   idx;
    reg [6:0]   sid;
    reg [3:0]   g_type;
    reg [31:0]  bin;
    reg [39:0]  bcd;
    reg [5:0]   cnt;
    reg [15:0]  crc;
    reg         crc_on;
    reg [7:0]   ch_r;
    reg         last_r;
    reg [7:0]   tx_data;
    reg         tx_start;
    wire        tx_busy;

    // time base (clk_100) and heartbeat
    reg [16:0]  ms_sub;
    reg [31:0]  up_ms;
    reg [15:0]  hb_cnt;
    reg         hb_pend;
    reg [23:0]  hb_seq;

    // record fields
    wire [7:0]  r_rid = r_rec[324:317];
    wire [7:0]  r_ev  = r_rec[316:309];
    wire [2:0]  r_st  = r_rec[308:306];
    wire [1:0]  r_sev = r_rec[305:304];
    wire [7:0]  r_pro = r_rec[87:80];

    // current token
    wire [10:0] tok    = tok_rom(tk);
    wire [3:0]  t_type = tok[10:7];
    wire [6:0]  t_arg  = tok[6:0];

    wire [7:0]  tk_next = ((tk == IDX_UP) && msg_hb) ? IDX_HB :
                          ( tk == IDX_HB)            ? IDX_CRC : (tk + 8'd1);

    // numeric / byte field selector
    reg [31:0] fval;
    always @* begin
        case (t_arg)
            7'd0:  fval = msg_hb ? 32'd2 : 32'd1;
            7'd1:  fval = {8'd0, cur_id};
            7'd2:  fval = cur_up;
            7'd3:  fval = {24'd0, r_rid};
            7'd4:  fval = {24'd0, r_rec[151:144]};   // sip octets
            7'd5:  fval = {24'd0, r_rec[143:136]};
            7'd6:  fval = {24'd0, r_rec[135:128]};
            7'd7:  fval = {24'd0, r_rec[127:120]};
            7'd8:  fval = {24'd0, r_rec[119:112]};   // dip octets
            7'd9:  fval = {24'd0, r_rec[111:104]};
            7'd10: fval = {24'd0, r_rec[103:96]};
            7'd11: fval = {24'd0, r_rec[95:88]};
            7'd12: fval = {16'd0, r_rec[79:64]};     // sport
            7'd13: fval = {16'd0, r_rec[63:48]};     // dport
            7'd14: fval = {16'd0, r_rec[47:32]};     // val
            7'd15: fval = {16'd0, r_rec[31:16]};     // sup
            7'd16: fval = {16'd0, r_rec[15:0]};      // lost
            7'd20: fval = {24'd0, r_rec[247:240]};   // smac bytes
            7'd21: fval = {24'd0, r_rec[239:232]};
            7'd22: fval = {24'd0, r_rec[231:224]};
            7'd23: fval = {24'd0, r_rec[223:216]};
            7'd24: fval = {24'd0, r_rec[215:208]};
            7'd25: fval = {24'd0, r_rec[207:200]};
            7'd26: fval = {24'd0, r_rec[199:192]};   // dmac bytes
            7'd27: fval = {24'd0, r_rec[191:184]};
            7'd28: fval = {24'd0, r_rec[183:176]};
            7'd29: fval = {24'd0, r_rec[175:168]};
            7'd30: fval = {24'd0, r_rec[167:160]};
            7'd31: fval = {24'd0, r_rec[159:152]};
            default: fval = 32'd0;
        endcase
    end

    // L4 protocol number -> name index (0 NONE, 1 TCP, 2 UDP, 3 ICMP, 4 OTHER)
    reg [6:0] pr_idx;
    always @* begin
        case (r_pro)
            8'd0:    pr_idx = 7'd0;
            8'd6:    pr_idx = 7'd1;
            8'd17:   pr_idx = 7'd2;
            8'd1:    pr_idx = 7'd3;
            default: pr_idx = 7'd4;
        endcase
    end

    // decimal digit extraction (leading zeros suppressed, at least one digit)
    reg [3:0] dfirst;
    always @* begin
        if      (bcd[39:36] != 4'd0) dfirst = 4'd9;
        else if (bcd[35:32] != 4'd0) dfirst = 4'd8;
        else if (bcd[31:28] != 4'd0) dfirst = 4'd7;
        else if (bcd[27:24] != 4'd0) dfirst = 4'd6;
        else if (bcd[23:20] != 4'd0) dfirst = 4'd5;
        else if (bcd[19:16] != 4'd0) dfirst = 4'd4;
        else if (bcd[15:12] != 4'd0) dfirst = 4'd3;
        else if (bcd[11:8]  != 4'd0) dfirst = 4'd2;
        else if (bcd[7:4]   != 4'd0) dfirst = 4'd1;
        else                         dfirst = 4'd0;
    end
    wire [3:0] dpos = dfirst - idx[3:0];
    wire [3:0] dig  = bcd[4*dpos +: 4];

    wire [4:0] slen = str_len(sid);

    // character generator for the current (token, idx)
    reg [7:0] ch;
    reg       last;
    always @* begin
        ch   = 8'h3F;
        last = 1'b1;
        case (g_type)
            T_DEC: begin
                ch   = 8'h30 + {4'd0, dig};
                last = (dpos == 4'd0);
            end
            T_HEX2: begin
                ch   = hexc(idx[0] ? bin[3:0] : bin[7:4]);
                last = idx[0];
            end
            T_CRC4: begin
                case (idx[1:0])
                    2'd0:    ch = hexc(crc[15:12]);
                    2'd1:    ch = hexc(crc[11:8]);
                    2'd2:    ch = hexc(crc[7:4]);
                    default: ch = hexc(crc[3:0]);
                endcase
                last = (idx[1:0] == 2'd3);
            end
            default: begin   // fixed strings and name lookups
                ch   = str_chr(sid, idx);
                last = (idx == (slen - 5'd1));
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // Main sequencer
    //--------------------------------------------------------------------------
    always @(posedge clk_100 or negedge rst_n_100) begin
        if (!rst_n_100) begin
            rq1 <= 1'b0; rq2 <= 1'b0; x_ack <= 1'b0;
            state <= S_IDLE; r_rec <= 325'd0; msg_hb <= 1'b0;
            cur_id <= 24'd0; cur_up <= 32'd0; tk <= 8'd0; idx <= 5'd0; sid <= 7'd0;
            g_type <= 4'd0; bin <= 32'd0; bcd <= 40'd0; cnt <= 6'd0;
            crc <= 16'hFFFF; crc_on <= 1'b0; ch_r <= 8'h00; last_r <= 1'b0;
            tx_data <= 8'h00; tx_start <= 1'b0;
            ms_sub <= 17'd0; up_ms <= 32'd0; hb_cnt <= 16'd0; hb_pend <= 1'b0; hb_seq <= 24'd0;
        end else begin
            rq1 <= x_req;
            rq2 <= rq1;
            tx_start <= 1'b0;

            // ---- millisecond time base + heartbeat timer
            if (ms_sub == 17'd99999) begin
                ms_sub <= 17'd0;
                up_ms  <= up_ms + 32'd1;
                if (HEARTBEAT_MS != 0) begin
                    if (hb_cnt == HEARTBEAT_MS - 1) begin hb_cnt <= 16'd0; hb_pend <= 1'b1; end
                    else hb_cnt <= hb_cnt + 16'd1;
                end
            end else begin
                ms_sub <= ms_sub + 17'd1;
            end

            case (state)
            //------------------------------------------------------------------
            S_IDLE: begin
                if (rq2 != x_ack) begin                 // alert record waiting
                    r_rec  <= x_data;
                    x_ack  <= rq2;                      // release the sender
                    msg_hb <= 1'b0;
                    cur_id <= x_data[303:280];
                    cur_up <= x_data[279:248];
                    crc    <= 16'hFFFF; crc_on <= 1'b1;
                    tk     <= 8'd0;
                    state  <= S_TOK;
                end else if (hb_pend) begin             // heartbeat due
                    hb_pend <= 1'b0;
                    hb_seq  <= hb_seq + 24'd1;
                    msg_hb  <= 1'b1;
                    cur_id  <= hb_seq + 24'd1;
                    cur_up  <= up_ms;
                    crc     <= 16'hFFFF; crc_on <= 1'b1;
                    tk      <= 8'd0;
                    state   <= S_TOK;
                end
            end
            //------------------------------------------------------------------
            S_TOK: begin
                g_type <= t_type;
                idx    <= 5'd0;
                case (t_type)
                    T_STR:   begin sid <= t_arg; state <= S_GEN; end
                    T_DEC:   begin bin <= fval; bcd <= 40'd0; cnt <= 6'd0; state <= S_CONV; end
                    T_HEX2:  begin bin <= fval; state <= S_GEN; end
                    T_SEVN:  begin sid <= SEV_BASE + {5'd0, r_sev}; state <= S_GEN; end
                    T_RULEN: begin sid <= RULE_BASE + ((r_rid <= 8'd15) ? r_rid[6:0] : 7'd0); state <= S_GEN; end
                    T_EVN:   begin sid <= EV_BASE   + ((r_ev  <= 8'd24) ? r_ev[6:0]  : 7'd0); state <= S_GEN; end
                    T_STN:   begin sid <= ST_BASE   + ((r_st  <= 3'd5)  ? {4'd0, r_st} : 7'd0); state <= S_GEN; end
                    T_PRN:   begin sid <= PR_BASE + pr_idx; state <= S_GEN; end
                    T_CRC4:  begin crc_on <= 1'b0; state <= S_GEN; end   // freeze CRC
                    default: state <= S_IDLE;                            // T_END: message complete
                endcase
            end
            //------------------------------------------------------------------
            S_CONV: begin        // 32-step binary -> BCD (double dabble)
                {bcd, bin} <= {bcd_adj(bcd), bin} << 1;
                cnt <= cnt + 6'd1;
                if (cnt == 6'd31) state <= S_GEN;
            end
            //------------------------------------------------------------------
            S_GEN: begin
                ch_r   <= ch;
                last_r <= last;
                state  <= S_SEND;
            end
            //------------------------------------------------------------------
            S_SEND: if (!tx_busy && !tx_start) begin
                tx_data  <= ch_r;
                tx_start <= 1'b1;
                if (crc_on) crc <= crc16_byte(crc, ch_r);
                state    <= S_WAIT;
            end
            S_WAIT: if (tx_busy) state <= S_DONE;
            S_DONE: if (!tx_busy) begin
                if (last_r) begin
                    tk    <= tk_next;
                    state <= S_TOK;
                end else begin
                    idx   <= idx + 5'd1;
                    state <= S_GEN;
                end
            end
            default: state <= S_IDLE;
            endcase
        end
    end

    uart_tx_core #(.CLKS_PER_BIT(CLKS_PER_BIT)) u_core (
        .clk(clk_100), .rst_n(rst_n_100),
        .tx_data(tx_data), .tx_start(tx_start),
        .tx_busy(tx_busy), .tx_out(uart_txd)
    );
endmodule

//==============================================================================
// uart_tx_core : 8N1 transmitter, LSB first, one start + one stop bit
//==============================================================================
module uart_tx_core #(
    parameter CLKS_PER_BIT = 5208
)(
    input  wire       clk,
    input  wire       rst_n,
    input  wire [7:0] tx_data,
    input  wire       tx_start,   // 1-clk pulse, ignored while busy
    output reg        tx_busy,
    output reg        tx_out
);
    reg [9:0]  sh;                // {stop, data[7:0], start}
    reg [3:0]  bitcnt;
    reg [12:0] baudcnt;           // up to 8191 clocks per bit

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_busy <= 1'b0;
            tx_out  <= 1'b1;
            sh      <= 10'h3FF;
            bitcnt  <= 4'd0;
            baudcnt <= 13'd0;
        end else if (!tx_busy) begin
            tx_out <= 1'b1;
            if (tx_start) begin
                sh      <= {1'b1, tx_data, 1'b0};
                tx_out  <= 1'b0;                  // start bit
                tx_busy <= 1'b1;
                bitcnt  <= 4'd0;
                baudcnt <= 13'd0;
            end
        end else begin
            if (baudcnt == CLKS_PER_BIT - 1) begin
                baudcnt <= 13'd0;
                if (bitcnt == 4'd9) begin          // stop bit finished
                    tx_busy <= 1'b0;
                    tx_out  <= 1'b1;
                end else begin
                    bitcnt <= bitcnt + 4'd1;
                    tx_out <= sh[bitcnt + 4'd1];
                end
            end else begin
                baudcnt <= baudcnt + 13'd1;
            end
        end
    end
endmodule
